from dataclasses import dataclass
import logging

from fastapi import Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse

logger = logging.getLogger("app.errors")


@dataclass
class AppError(Exception):
    status_code: int
    code: str
    detail: str
    headers: dict[str, str] | None = None


async def app_error_handler(request: Request, exc: AppError) -> JSONResponse:
    return JSONResponse(
        status_code=exc.status_code,
        headers=exc.headers,
        content={
            "type": f"https://career-coach.local/errors/{exc.code.lower()}",
            "title": exc.code,
            "status": exc.status_code,
            "detail": exc.detail,
            "instance": request.url.path,
            "requestId": getattr(request.state, "request_id", None),
        },
    )


async def validation_error_handler(request: Request, exc: RequestValidationError) -> JSONResponse:
    errors = [
        {"field": ".".join(str(part) for part in item["loc"][1:]), "message": item["msg"]}
        for item in exc.errors()
    ]
    return JSONResponse(
        status_code=422,
        content={
            "type": "https://career-coach.local/errors/validation_error",
            "title": "VALIDATION_ERROR",
            "status": 422,
            "detail": "请求参数校验失败",
            "instance": request.url.path,
            "requestId": getattr(request.state, "request_id", None),
            "errors": errors,
        },
    )


def not_found(resource: str) -> AppError:
    return AppError(404, "NOT_FOUND", f"{resource}不存在")


async def unexpected_error_handler(request: Request, exc: Exception) -> JSONResponse:
    request_id = getattr(request.state, "request_id", None)
    logger.exception(
        "request.unexpected_error",
        exc_info=(type(exc), exc, exc.__traceback__),
        extra={
            "request_id": request_id,
            "method": request.method,
            "path": request.url.path,
            "status_code": 500,
        },
    )
    return JSONResponse(
        status_code=500,
        content={
            "type": "https://career-coach.local/errors/internal_error",
            "title": "INTERNAL_ERROR",
            "status": 500,
            "detail": "服务暂时不可用，请稍后重试",
            "instance": request.url.path,
            "requestId": request_id,
        },
    )

"""兼容历史数据：把旧维度名称统一成当前叫法。

数据库里 rename 之前生成的评分摘要、建议、微课仍会带「感染力」，
在读取并再次喂给模型前统一替换，避免旧文案扩散到新内容里。
"""

from __future__ import annotations

LEGACY_LABELS = {
    # 最初叫「感染力」，后来并入「正确性」，最终并入「信息完整」
    "感染力": "信息完整",
    "逻辑性": "内容与逻辑",
    "针对性": "贴合问题",
    "正确性": "信息完整",
    "简洁度": "表达干净",
    "得体性": "表达干净",
    "五维": "四维",
    "impact": "correctness",
}


def modernize(value):
    """递归替换字符串里的旧维度名称。"""
    if isinstance(value, str):
        for old, new in LEGACY_LABELS.items():
            if old in value:
                value = value.replace(old, new)
        return value
    if isinstance(value, list):
        return [modernize(item) for item in value]
    if isinstance(value, dict):
        result = {}
        for key, item in value.items():
            new_key = LEGACY_LABELS.get(key, key)
            result[new_key] = modernize(item)
        return result
    return value

import json
import logging
import sys
from datetime import datetime, timezone


class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, object] = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
        }
        for name in ("request_id", "method", "path", "status_code", "duration_ms"):
            if hasattr(record, name):
                payload[name] = getattr(record, name)
        if record.exc_info:
            payload["exception"] = self.formatException(record.exc_info)
        return json.dumps(payload, ensure_ascii=False)


def configure_logging(level: str) -> None:
    handler = logging.StreamHandler(sys.stdout)
    handler.setFormatter(JsonFormatter())
    root = logging.getLogger()
    root.handlers.clear()
    root.addHandler(handler)
    root.setLevel(level)

from datetime import datetime, timezone
from typing import Any


def ok(data: Any) -> dict[str, Any]:
    return {"data": data, "meta": {"timestamp": datetime.now(timezone.utc).isoformat()}}

from datetime import datetime, timezone
from typing import Any

from pydantic import BaseModel, ConfigDict, SerializerFunctionWrapHandler, field_serializer


def to_camel(value: str) -> str:
    head, *tail = value.split("_")
    return head + "".join(part.capitalize() for part in tail)


class ApiModel(BaseModel):
    model_config = ConfigDict(
        alias_generator=to_camel,
        populate_by_name=True,
        from_attributes=True,
    )

    @field_serializer("*", mode="wrap")
    def _datetime_as_utc(self, value: Any, handler: SerializerFunctionWrapHandler) -> Any:
        # MySQL / SQLite 读回的 datetime 不带时区；库内一律存 UTC，输出时补上 +00:00，
        # 否则浏览器会按本地时区解析（东八区整场计时会多出 480 分钟）。
        if isinstance(value, datetime) and value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return handler(value)

"""个人数据导出：给学员一份可带走的 JSON（合规与信任）。

包含：账号资料、训练会话与逐轮原文、评分与证据、训练计划、话术、故事。
不包含：他人数据、内部管理字段、模型提示词。
"""

from __future__ import annotations

from datetime import datetime, timezone

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from app.db.models import (
    Evaluation,
    EvaluationEvidence,
    Message,
    Scene,
    Script,
    TrainingPlan,
    TrainingSession,
    User,
)

SCHEMA_VERSION = 1


def _iso(value: datetime | None) -> str | None:
    return value.isoformat() if value else None


async def export_user_data(session: AsyncSession, user: User) -> dict:
    sessions = (
        await session.scalars(
            select(TrainingSession)
            .where(TrainingSession.user_id == user.id)
            .order_by(TrainingSession.started_at)
        )
    ).all()
    scene_ids = {item.scene_id for item in sessions}
    scenes = {}
    if scene_ids:
        rows = (await session.scalars(select(Scene).where(Scene.id.in_(scene_ids)))).all()
        scenes = {row.id: row for row in rows}

    evaluation_rows = (
        await session.scalars(select(Evaluation).where(Evaluation.user_id == user.id))
    ).all()
    evaluations = {row.session_id: row for row in evaluation_rows}

    evidence_rows = (
        await session.scalars(
            select(EvaluationEvidence).where(
                EvaluationEvidence.evaluation_id.in_([row.id for row in evaluation_rows] or [""])
            )
        )
    ).all()
    evidence_by_eval: dict[str, list[EvaluationEvidence]] = {}
    for row in evidence_rows:
        evidence_by_eval.setdefault(row.evaluation_id, []).append(row)

    messages = (
        await session.scalars(
            select(Message)
            .where(Message.session_id.in_([item.id for item in sessions] or [""]))
            .order_by(Message.round_no, Message.created_at)
        )
    ).all()
    messages_by_session: dict[str, list[Message]] = {}
    for row in messages:
        messages_by_session.setdefault(row.session_id, []).append(row)

    payload_sessions = []
    for item in sessions:
        evaluation = evaluations.get(item.id)
        payload_sessions.append(
            {
                "id": item.id,
                "sceneTitle": scenes[item.scene_id].title if item.scene_id in scenes else None,
                "channel": item.channel,
                "status": item.status,
                "startedAt": _iso(item.started_at),
                "finishedAt": _iso(item.finished_at),
                "durationSeconds": item.duration_seconds,
                "rounds": [
                    {"round": row.round_no, "speaker": row.speaker, "content": row.content, "at": _iso(row.created_at)}
                    for row in messages_by_session.get(item.id, [])
                ],
                "evaluation": (
                    {
                        "overallScore": evaluation.overall_score,
                        "scores": {
                            "logic": evaluation.logic_score,
                            "relevance": evaluation.relevance_score,
                            "correctness": evaluation.correctness_score,
                            "concision": evaluation.concision_score,
                        },
                        "summary": evaluation.summary,
                        "suggestions": evaluation.suggestions,
                        "degraded": evaluation.degraded,
                        "reviewRequired": evaluation.review_required,
                        "assessment": evaluation.assessment,
                        "revisionHistory": evaluation.revision_history or [],
                        "evidence": [
                            {
                                "round": evidence.round_no,
                                "dimension": evidence.dimension,
                                "quote": evidence.quote,
                                "reason": evidence.reason,
                            }
                            for evidence in evidence_by_eval.get(evaluation.id, [])
                        ],
                    }
                    if evaluation
                    else None
                ),
            }
        )

    plans = (
        await session.scalars(
            select(TrainingPlan)
            .where(TrainingPlan.user_id == user.id)
            .order_by(TrainingPlan.sequence)
        )
    ).all()
    scripts = (
        await session.scalars(
            select(Script).where(Script.user_id == user.id).order_by(Script.created_at)
        )
    ).all()

    return {
        "schemaVersion": SCHEMA_VERSION,
        "exportedAt": datetime.now(timezone.utc).isoformat(),
        "account": {
            "id": user.id,
            "email": user.email,
            "displayName": user.display_name,
            "bio": user.bio,
            "createdAt": _iso(user.created_at),
        },
        "sessions": payload_sessions,
        "plans": [
            {
                "id": plan.id,
                "sequence": plan.sequence,
                "status": plan.status,
                "createdAt": _iso(plan.created_at),
                "tasks": plan.tasks,
            }
            for plan in plans
        ],
        "scripts": [
            {
                "id": item.id,
                "sceneId": item.scene_id,
                "style": item.style,
                "original": item.original,
                "content": item.content,
                "createdAt": _iso(item.created_at),
            }
            for item in scripts
        ],
    }

import csv
from datetime import datetime, timedelta, timezone
from io import StringIO
from typing import Annotated

from fastapi import APIRouter, Depends, Query
from sqlalchemy import select
from fastapi.responses import StreamingResponse
from sqlalchemy import func, or_, select
from sqlalchemy.ext.asyncio import AsyncSession

from app.core.errors import AppError, not_found
from app.core.responses import ok
from app.core.security import AdminUser, hash_password
from app.db.base import get_session
from app.db.models import (
    AuditLog,
    ModelUsageDaily,
    PasswordResetRequest,
    Course,
    Evaluation,
    RefreshToken,
    Scene,
    TrainingSession,
    User,
)
from app.features.account.deletion import purge_user_rows
from app.features.admin.schemas import CourseAdminInput, SceneAdminInput, UserAdminUpdate
from app.features.scenes.taxonomy import normalize_bank

DEFAULT_RESET_PASSWORD = "123456789"

# 自动化测试与验收脚本注册账号时使用的邮箱前缀
TEST_EMAIL_PREFIXES = (
    "simli-", "imm-", "e2e-", "a11y-", "hint-", "nav-", "probe-", "repro-",
    "self-review-", "api-", "bench-", "load-", "test-",
    "bank-", "group-", "resume-", "coding-", "smoke-", "latency-", "en-", "py-",
    "seg-", "jdcheck-", "room-", "jd-", "vs-", "vt-", "pv2-", "pv-", "v2-",
    "loop2-", "loop-",
)
DEMO_EMAILS = {"student@example.com", "admin@example.com"}

router = APIRouter(prefix="/admin", tags=["后台管理"])
DbSession = Annotated[AsyncSession, Depends(get_session)]


@router.get("/overview")
async def overview(_: AdminUser, session: DbSession) -> dict:
    async def count(model: type) -> int:
        return int((await session.scalar(select(func.count()).select_from(model))) or 0)

    average = await session.scalar(select(func.avg(Evaluation.overall_score)))
    return ok({
        "users": int((await session.scalar(
            select(func.count()).select_from(User).where(User.role == "STUDENT")
        )) or 0),
        "activeUsers": int((await session.scalar(
            select(func.count()).select_from(User).where(User.active.is_(True), User.role == "STUDENT")
        )) or 0),
        "scenes": await count(Scene),
        "activeScenes": int((await session.scalar(select(func.count()).select_from(Scene).where(Scene.active.is_(True)))) or 0),
        "courses": await count(Course),
        "activeCourses": int((await session.scalar(select(func.count()).select_from(Course).where(Course.active.is_(True)))) or 0),
        # 0 轮的占位会话（进房间时 prepare 建的）不算训练场次，否则看板会虚高
        "sessions": int((await session.scalar(
            select(func.count()).select_from(TrainingSession).where(
                or_(TrainingSession.status != "ACTIVE", TrainingSession.current_round > 0)
            )
        )) or 0),
        "averageScore": round(float(average or 0), 1),
    })


@router.get("/users")
async def users(
    _: AdminUser,
    session: DbSession,
    page: Annotated[int, Query(ge=0)] = 0,
    size: Annotated[int, Query(ge=1, le=100)] = 20,
    q: str | None = None,
) -> dict:
    statement = select(User).order_by(User.created_at.desc())
    if q and q.strip():
        term = f"%{q.strip().lower()}%"
        statement = statement.where(func.lower(User.email).like(term) | func.lower(User.display_name).like(term))
    rows = (await session.scalars(statement.offset(page * size).limit(size))).all()
    return ok([{
        "id": item.id, "email": item.email, "displayName": item.display_name,
        "role": item.role, "active": item.active, "bio": item.bio,
        "createdAt": item.created_at.isoformat(),
    } for item in rows])


@router.post("/users/cleanup-test")
async def cleanup_test_users(body: dict, _: AdminUser, session: DbSession) -> dict:
    """按邮箱前缀清理测试脚本留下的账号：dryRun 只统计，正式执行会连同会话与报告一起删除。"""
    dry_run = bool(body.get("dryRun", True))
    rows = (await session.scalars(select(User).where(User.role != "ADMIN"))).all()
    targets = [
        item for item in rows
        if item.email.lower().startswith(TEST_EMAIL_PREFIXES) and item.email not in DEMO_EMAILS
    ]
    if dry_run:
        return ok({"count": len(targets), "sample": [item.email for item in targets[:5]]})

    deleted = 0
    for user in targets:
        session_ids = list((await session.scalars(
            select(TrainingSession.id).where(TrainingSession.user_id == user.id)
        )).all())
        await purge_user_rows(session, user, session_ids)
        await session.delete(user)
        deleted += 1
    await session.commit()
    return ok({"count": deleted})


@router.post("/users/{user_id}/reset-password")
async def reset_password(user_id: str, _: AdminUser, session: DbSession) -> dict:
    user = await session.get(User, user_id)
    if user is None:
        raise not_found("用户")
    if user.role == "ADMIN":
        raise AppError(422, "CANNOT_RESET_ADMIN", "管理员密码请在本人的个人资料页修改")
    temporary = DEFAULT_RESET_PASSWORD
    user.password_hash = hash_password(temporary)
    await session.execute(
        RefreshToken.__table__.delete().where(RefreshToken.user_id == user.id)
    )
    await session.commit()
    return ok({"temporaryPassword": temporary})


@router.patch("/users/{user_id}")
async def update_user(user_id: str, body: UserAdminUpdate, admin: AdminUser, session: DbSession) -> dict:
    user = await session.get(User, user_id)
    if user is None:
        raise not_found("用户")
    changes = body.model_dump(exclude_unset=True)
    if not changes:
        raise AppError(422, "EMPTY_UPDATE", "请至少提交一个要修改的字段")
    if user.id == admin.id and changes.get("active") is False:
        raise AppError(422, "CANNOT_DISABLE_SELF", "不能停用当前管理员账号")
    if user.role == "ADMIN" and changes.get("active") is False:
        admins = await session.scalar(select(func.count()).select_from(User).where(User.role == "ADMIN", User.active.is_(True)))
        if admins <= 1:
            raise AppError(422, "LAST_ADMIN", "系统至少需要保留一个启用的管理员")
    for key, value in changes.items():
        setattr(user, key, value)
    if changes.get("active") is False:
        await session.execute(
            RefreshToken.__table__.delete().where(RefreshToken.user_id == user.id)
        )
    await session.commit()
    return ok({"id": user.id, "role": user.role, "active": user.active})


async def scene_coverage_stats(session: DbSession) -> dict[str, tuple[int, int]]:
    rows = (
        await session.execute(
            select(TrainingSession.scene_id, TrainingSession.covered_count)
        )
    ).all()
    stats: dict[str, tuple[int, int]] = {}
    for scene_id, covered in rows:
        total, with_cover = stats.get(scene_id, (0, 0))
        stats[scene_id] = (total + 1, with_cover + (1 if (covered or 0) > 0 else 0))
    return stats


@router.get("/scenes")
async def scenes(_: AdminUser, session: DbSession) -> dict:
    rows = (await session.scalars(select(Scene).order_by(Scene.created_at.desc()))).all()
    stats = await scene_coverage_stats(session)
    return ok([{
        "id": item.id, "category": item.category, "title": item.title,
        "industry": item.industry, "position": item.position, "roleName": item.role_name,
        "difficulty": item.difficulty, "background": item.background, "goal": item.goal,
        "tags": item.tags, "openingLine": item.opening_line,
        "coreIdea": item.core_idea or "", "questionBank": normalize_bank(item.question_bank), "active": item.active,
        "sessionCount": stats.get(item.id, (0, 0))[0],
        "coveredSessionCount": stats.get(item.id, (0, 0))[1],
    } for item in rows])


@router.post("/scenes", status_code=201)
async def create_scene(body: SceneAdminInput, _: AdminUser, session: DbSession) -> dict:
    payload = body.model_dump()
    payload["question_bank"] = [item.model_dump(by_alias=True, exclude_none=True) for item in body.question_bank]
    scene = Scene(**payload)
    session.add(scene)
    await session.commit()
    return ok({"id": scene.id})


@router.patch("/scenes/{scene_id}")
async def update_scene(scene_id: str, body: SceneAdminInput, _: AdminUser, session: DbSession) -> dict:
    scene = await session.get(Scene, scene_id)
    if scene is None:
        raise not_found("面试场景")
    payload = body.model_dump()
    payload["question_bank"] = [item.model_dump(by_alias=True, exclude_none=True) for item in body.question_bank]
    for key, value in payload.items():
        setattr(scene, key, value)
    await session.commit()
    return ok({"id": scene.id, "active": scene.active})


@router.delete("/scenes/{scene_id}")
async def deactivate_scene(scene_id: str, _: AdminUser, session: DbSession) -> dict:
    scene = await session.get(Scene, scene_id)
    if scene is None:
        raise not_found("面试场景")
    scene.active = False
    await session.commit()
    return ok({"id": scene.id, "active": False})


