SCORE_LABELS = {'logic': '内容与逻辑', 'relevance': '贴合问题', 'correctness': '信息完整', 'concision': '表达干净'}
RECENT_SAMPLES = 5
TREND_SAMPLES = 20
MIN_TREND_SAMPLES = 3


def scores(evaluation: Evaluation) -> dict:
    return {key: getattr(evaluation, f'{key}_score') for key in SCORE_LABELS}


def training_time(training: TrainingSession) -> datetime:
    value = training.finished_at or training.started_at
    return value.replace(tzinfo=timezone.utc) if value.tzinfo is None else value


def reference(training: TrainingSession, title: str, has_resume: bool = False) -> dict:
    return {'anchorSessionId': training.id, 'sceneId': training.scene_id, 'sceneTitle': title, 'channel': training.channel, 'depth': training.depth, 'mode': training.mode, 'hasResume': has_resume, 'hasJd': bool(training.jd_text), 'trainedAt': training_time(training).isoformat()}


async def overview(db: AsyncSession, user_id: str) -> dict:
    recent = func.coalesce(TrainingSession.finished_at, TrainingSession.started_at) >= datetime.now(timezone.utc) - timedelta(days=30)
    rows = (await db.execute(select(TrainingSession.channel, func.count(), func.sum(case((recent, 1), else_=0))).where(TrainingSession.user_id == user_id, TrainingSession.status == 'FINISHED').group_by(TrainingSession.channel))).all()
    counts = {key: 0 for key in ('TEXT', 'VOICE', 'VIDEO')}
    for channel, count, _ in rows:
        if channel in counts:
            counts[channel] = count
    return {'trainingCount': sum(row[1] for row in rows), 'recentTrainingCount': sum(int(row[2] or 0) for row in rows), 'recentDays': 30, 'channelCounts': counts}


def delivery_summary(training: TrainingSession | None) -> dict | None:
    if training is None or training.channel == 'TEXT':
        return None
    raw = training.delivery or {}
    def numbers(source, keys):
        return {key: value for key in keys if isinstance(value := source.get(key), (int, float)) and not isinstance(value, bool) and isfinite(value) and value >= 0}
    speech = numbers(raw, ('speechRate', 'pauseCount', 'longestPause', 'fillerTotal'))
    vision = raw.get('vision') or {}
    camera = numbers(vision, ('faceRatio', 'eyeContactRatio', 'headStability')) if isinstance(vision, dict) and vision.get('available') is not False else {}
    return {'sessionId': training.id, 'channel': training.channel, 'speech': speech, 'camera': camera}


async def _scored_history(db: AsyncSession, formal: tuple, ordering) -> list:
    # Filter choices come from the learner's actual scored history, including retired scenes.
    return (await db.execute(select(TrainingSession, Scene.title).options(load_only(TrainingSession.id, TrainingSession.scene_id, TrainingSession.channel, TrainingSession.depth, TrainingSession.mode, TrainingSession.language, TrainingSession.jd_text, TrainingSession.started_at, TrainingSession.finished_at, TrainingSession.assessment_context)).join(Evaluation, Evaluation.session_id == TrainingSession.id).join(Scene, Scene.id == TrainingSession.scene_id).where(*formal).order_by(*ordering))).all()


async def _matching_samples(db: AsyncSession, selected: tuple, formal: tuple, ordering) -> tuple[str | None, int, list]:
    """同条件的正式评分样本：返回 (参考简历, 总匹配数, 最近 TREND_SAMPLES 条)。"""
    context = await db.get(ResumeContext, selected[0].id)
    resume = context.content if context else None
    query = select(Evaluation, TrainingSession).join(TrainingSession, TrainingSession.id == Evaluation.session_id).outerjoin(ResumeContext, ResumeContext.session_id == TrainingSession.id).where(*formal, *condition_filters(selected[0], resume))
    total = int(await db.scalar(select(func.count()).select_from(query.subquery())) or 0)
    rows = (await db.execute(query.order_by(*ordering).limit(TREND_SAMPLES))).all()
    return resume, total, rows


def _recent_aggregates(recent: list) -> tuple[dict, list[str]]:
    """近期样本的四维均分与风格标签（最多 3 个）。"""
    averages = {key: round(sum(getattr(item[0], f'{key}_score') for item in recent) / len(recent), 2) for key in SCORE_LABELS} if recent else {}
    tag_counts = {}
    for evaluation, _ in recent:
        for tag in evaluation.style_tags or []:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
    tags = [f'{tag} ×{count}' for tag, count in sorted(tag_counts.items(), key=lambda item: (-item[1], item[0]))[:3]]
    return averages, tags


async def dashboard_data(db: AsyncSession, user_id: str, channel: str | None = None, scene_id: str | None = None, anchor_session_id: str | None = None) -> dict:
    totals = await overview(db, user_id)
    formal = (Evaluation.user_id == user_id, TrainingSession.user_id == user_id, *formal_filters())
    ordering = training_order()
    options = await _scored_history(db, formal, ordering)
    candidates = [row for row in options if (not channel or row[0].channel == channel) and (not scene_id or row[0].scene_id == scene_id)]
    selected = next((row for row in candidates if row[0].id == anchor_session_id), None) if anchor_session_id else next(iter(candidates), None)
    if anchor_session_id and selected is None:
        raise not_found('可比较的参考训练')
    selected_resume, total_matches, matching = (await _matching_samples(db, selected, formal, ordering)) if selected else (None, 0, [])
    recent = matching[:RECENT_SAMPLES]
    averages, style_tags = _recent_aggregates(recent)
    latest, latest_training = matching[0] if matching else (None, None)
    return {
        'overview': totals, 'trainingCount': totals['trainingCount'],
        'condition': reference(selected[0], selected[1], selected_resume is not None) if selected else None,
        'filterOptions': {'scenes': list({row[0].scene_id: {'id': row[0].scene_id, 'title': row[1]} for row in options}.values()), 'anchors': [reference(row[0], row[1]) for row in candidates]},
        'formalEvaluationCount': total_matches, 'sampleCount': len(matching), 'recentSampleCount': len(recent), 'minimumTrendSamples': MIN_TREND_SAMPLES, 'trendReady': len(matching) >= MIN_TREND_SAMPLES,
        'latestScore': latest.overall_score if latest else None, 'latestSessionId': latest_training.id if latest_training else None, 'latestTrainingAt': training_time(latest_training).isoformat() if latest_training else None,
        'recentAverage': round(sum(item[0].overall_score for item in recent) / len(recent), 1) if recent else None,
        'dimensions': scores(latest) if latest else None, 'averageDimensions': averages or None,
        'styleTags': style_tags,
        'weaknesses': [{'dimension': SCORE_LABELS[key], 'averageScore': value, 'sampleCount': len(recent)} for key, value in sorted(averages.items(), key=lambda item: item[1])[:2]] if len(set(averages.values())) > 1 else [],
        'summary': training_summary(recent, averages, SCORE_LABELS),
        'trends': [{'sessionId': training.id, 'date': training_time(training).isoformat(), 'score': evaluation.overall_score, 'dimensions': scores(evaluation)} for evaluation, training in reversed(matching)],
        'delivery': delivery_summary(latest_training),
    }

"""从同条件正式评分整理总结；读取看板不新增模型调用。"""

NEXT_ACTIONS = {
    'logic': '下一次先用一句话给出结论，再说明理由或关键步骤，让每一段都围绕同一个观点展开。',
    'relevance': '下一次先直接回答题目最关心的点，再补一条相关事实；结束前检查有没有答到原问题。',
    'correctness': '按题型补全关键信息：经历题交代职责、行动和结果，知识题说明机制与边界，只补充真实可核实的信息。',
    'concision': '下一次删去重复铺垫，每个观点只保留一条有用的事实，回答后再用一句话收束重点。',
}


def training_summary(recent, averages: dict[str, float], labels: dict[str, str]) -> dict:
    count = len(recent)
    if not count:
        return {
            'sampleCount': 0,
            'text': '当前比较范围内暂无正式评分，暂时不能总结优势、短板或变化。',
            'nextAction': '完成一次场景训练并生成正式评分后，这里会结合成绩和复盘给出总结。',
            'reportSummary': None,
        }
    latest = recent[0][0]
    average = round(sum(item[0].overall_score for item in recent) / count, 1)
    text = f'近 {count} 次同条件正式评分均分 {average:g} 分，最近一次 {latest.overall_score:g} 分。'
    if count < 3:
        text += f'目前只有 {count} 次可比较记录，暂不判断趋势。'
    low, high = min(averages.values()), max(averages.values())
    if high == low:
        text += f'四项能力均分均为 {low:g}/5，没有明显的单一短板。'
        action = '下一次按题型补全关键信息，先直接回答问题，再交代依据和结果或适用边界，最后删去重复铺垫。'
    else:
        stronger = '、'.join(labels[key] for key, score in averages.items() if score == high)
        weaker = '、'.join(labels[key] for key, score in averages.items() if score == low)
        text += f'相对更稳的是{stronger}（{high:g}/5），优先练习{weaker}（{low:g}/5）。'
        focus = next(key for key, score in averages.items() if score == low)
        action = NEXT_ACTIONS[focus]
    report = latest.summary.strip() if isinstance(latest.summary, str) else ''
    return {'sampleCount': count, 'text': text, 'nextAction': action, 'reportSummary': report[:600] or None}

"""Validate role-specific assessment against this attempt's rubric and quotes."""
import copy
import re


def _verified_evidence(draft: dict, by_round: dict, matched: set) -> list[dict]:
    """只保留逐字出现在对应回答里的引用。"""
    raw_evidence = draft.get("evidence") if isinstance(draft.get("evidence"), list) else []
    evidence = []
    for item in raw_evidence[:4]:
        if not isinstance(item, dict):
            continue
        turn = by_round.get(item.get("roundNo"))
        quote = item.get("quote")
        if turn and turn.round_no in matched and isinstance(quote, str) and len(quote.strip()) >= 4 and quote in turn.answer.content:
            evidence.append({"roundNo": turn.round_no, "quote": quote[:500], "answerMessageId": turn.answer.id})
    return evidence


def _competency_status(draft: dict, matched: set, evidence: list, missing: list, technical_checks: list) -> str:
    if evidence and any(isinstance(check, dict) and check.get("verdict") in {"ERROR", "UNCERTAIN"}
                        and check.get("roundNo") in matched for check in technical_checks):
        return "UNCERTAIN"
    if evidence and draft.get("status") == "UNCERTAIN":
        return "UNCERTAIN"
    if evidence and not missing and draft.get("status") == "DEMONSTRATED":
        return "DEMONSTRATED"
    return "NOT_COVERED" if not matched else "LIMITED"


def _matrix_entry(criterion: dict, context: dict, trace: list, turns: list, by_round: dict, payload) -> dict:
    matched = {turn.round_no for turn in turns if re.search(criterion.get("match", "^$"), turn.question.content)}
    matched.update(item["roundNo"] for item in trace if item.get("criterionId") == criterion["id"])
    draft = next((item for item in payload.professional_matrix if isinstance(item, dict) and item.get("competencyId") == criterion["id"]), {})
    evidence = _verified_evidence(draft, by_round, matched)
    points = criterion["points"]
    raw_points = draft.get("metPoints") if isinstance(draft.get("metPoints"), list) else []
    met = [point for point in points if point in raw_points] if evidence else []
    missing = [point for point in points if point not in met]
    status = _competency_status(draft, matched, evidence, missing, payload.technical_checks)
    reason = draft.get("reason") if evidence else None
    return {"competencyId": criterion["id"], "name": criterion["name"], "status": status,
            "expectedPoints": points, "metPoints": met, "missingPoints": missing,
            "evidence": evidence, "reason": str(reason)[:600] if reason else ("本场尚未考察这一项。" if not matched else "已有相关回答，仍需补充可核对的专业要点依据。"),
            "rubricVersion": criterion.get("version", context.get("version", "v1")),
            "reviewed": bool(criterion.get("reviewed", False)), "referenceUrl": criterion.get("referenceUrl")}


def _transfer_result(transfer: dict, matrix: list, turns: list, conflicts: list) -> str:
    target = [item for item in matrix if item["competencyId"] in transfer.get("competencies", [])]
    if len(turns) < 2:
        return "INSUFFICIENT_SAMPLE"
    if conflicts:
        return "AWAITING_REVIEW"
    if target and all(item["status"] == "DEMONSTRATED" for item in target):
        return "INDEPENDENT_APPLICATION"
    return "NEEDS_PRACTICE"


def assessment_snapshot(payload, training, turns, conflicts, model: str) -> dict:
    from app.features.evaluations.standards import standard_metadata
    context = training.assessment_context or {}
    trace = context.get("evidenceTrace", [])
    by_round = {turn.round_no: turn for turn in turns}
    matrix = [_matrix_entry(criterion, context, trace, turns, by_round, payload) for criterion in context.get("criteria", [])]
    transfer = copy.deepcopy(context.get("transfer"))
    if transfer:
        transfer["result"] = _transfer_result(transfer, matrix, turns, conflicts)
        transfer["answeredRounds"] = len(turns)
        transfer["note"] = "仅针对本次新题与参考要点的模型判断，不与原题分数直接连线。"
    return {"version": context.get("version", "interview-2026-11-v1"), "model": model,
            "scoringStandard": standard_metadata(context),
            "rubricVersion": context.get("rubricVersion", "legacy"), "purpose": context.get("purpose", "PRACTICE"),
            "hintUses": int(context.get("hintUses", 0)), "professionalMatrix": matrix,
            "evidenceTrace": copy.deepcopy(trace), "consistencyConflicts": conflicts,
            "transfer": transfer}

"""Validate public model checks and detect score/check contradictions."""


def validated_technical_checks(checks, turns) -> list[dict]:
    answers = {turn.round_no: turn.answer.content for turn in turns}
    result = []
    for item in checks:
        if not isinstance(item, dict) or item.get("verdict") not in {"CORRECT", "ERROR", "UNCERTAIN"}:
            continue
        quote, reason = item.get("quote"), item.get("reason")
        if isinstance(quote, str) and quote.strip() and isinstance(reason, str) and reason.strip() and quote in answers.get(item.get("roundNo"), ""):
            result.append({"roundNo": item["roundNo"], "quote": quote[:500],
                           "verdict": item["verdict"], "reason": reason[:1000]})
    return result[:4]


def score_conflicts(scores: dict, checks: list[dict]) -> list[dict]:
    if scores.get("logic", 0) < 5:
        return []
    return [{"roundNo": item["roundNo"], "quote": item["quote"],
             "reason": "专业核查标记为错误，但内容与逻辑为最高档，需要核对该错误的重要性与评分依据。"}
            for item in checks if item["verdict"] == "ERROR"]

"""保守识别口头语；单字语气词须独立出现，避免命中“名额、金额”等正常词。"""
import re


def count_fillers(text: str, words) -> dict[str, int]:
    counts = {}
    for word in words:
        if len(word) == 1:
            matches = re.findall(r'(?<![\w])' + re.escape(word) + r'+(?![\w])', text)
            count = sum(len(match) for match in matches)
        else:
            count = text.count(word)
        if count:
            counts[word] = count
    return counts

"""客观可复现的子指标：不依赖大模型，纯规则计算。

输出的 0–1 分数会与模型评分加权，并对模型给出「已算指标」提示，
让评分有可核查的锚点，而不是全凭模型主观判断。
"""

from __future__ import annotations

import re
from collections import Counter
from app.features.evaluations.fillers import count_fillers
from app.features.training.language import affirmative_occurrences, constructive_uncertainty

FILLERS = ["然后", "就是", "那个", "其实", "反正", "所以说", "嗯", "额", "这个", "的话"]
STRUCTURE_MARKERS = ["首先", "其次", "然后", "最后", "因此", "所以", "因为", "例如", "举个例子", "总结", "一是", "二是"]
NUMBERS = re.compile(r"\d+(?:\.\d+)?\s*(?:%|ms|s|万|千|个|人|天|小时|年|月|k|K)?")
# 常见「答非所问」信号：完全不给结论的回避词
EVASIVE = ["不知道", "没想过", "无所谓", "看情况", "都行", "随便"]


def _split_sentences(text: str) -> list[str]:
    return [item for item in re.split(r"[。！？!?\n]", text) if item.strip()]


def _keywords(text: str) -> set[str]:
    """粗粒度关键词：2 字以上的中文片段与英文词。"""
    words = set(re.findall(r"[\u4e00-\u9fff]{2,}", text))
    words.update(word.lower() for word in re.findall(r"[A-Za-z]{3,}", text))
    stop = {"什么", "怎么", "这个", "那个", "可以", "我们", "你们", "他们", "因为", "所以", "如果", "就是"}
    return {word for word in words if word not in stop}


def _bigrams(text: str) -> set[str]:
    clean = re.sub(r"[\s，。！？、,.!?]", "", text)
    return {clean[index:index + 2] for index in range(len(clean) - 1)}


QUESTION_SIGNALS = {
    "为什么": ["因为", "考虑到", "希望", "看重", "觉得"],
    "怎么": ["先", "然后", "首先", "其次", "通过", "用", "步骤"],
    "如何": ["先", "然后", "首先", "通过", "用", "方法"],
    "多少": ["k", "元", "万", "%", "左右", "期望"],
    "什么": ["是", "指", "包括", "意思是"],
    "能不能": ["可以", "能", "能够"],
}


def answer_relevance(question: str | None, answer: str) -> float:
    """问题与回答的贴合度：关键词/二元组重合 + 问句类型是否被回应。"""
    if not answer.strip():
        return 0.0
    if not question:
        return 0.5

    asked = _keywords(question)
    hit_keywords = sum(1 for word in asked if word in answer) / max(1, len(asked))
    question_grams, answer_grams = _bigrams(question), _bigrams(answer)
    overlap = len(question_grams & answer_grams) / max(1, len(question_grams))

    type_score = 0.5
    for marker, expected in QUESTION_SIGNALS.items():
        if marker in question:
            type_score = 1.0 if any(word in answer for word in expected) else 0.2
            break

    length_score = min(1.0, len(answer) / 40)
    if any(word in answer for word in EVASIVE) and len(answer) < 30:
        length_score *= 0.4

    score = 0.3 * hit_keywords + 0.2 * overlap + 0.35 * type_score + 0.15 * length_score
    return round(min(1.0, score), 2)


def structure_ratio(text: str) -> float:
    """连接词密度：每 100 字出现几个结构标记。"""
    length = max(1, len(re.sub(r"\s", "", text)))
    hits = sum(text.count(marker) for marker in STRUCTURE_MARKERS)
    return min(1.0, hits / (length / 100) / 3) if length >= 40 else 0.0


def redundancy_ratio(text: str) -> float:
    """重复度：重复 4-gram 占全部 4-gram 的比例（越高越啰嗦）。"""
    clean = re.sub(r"\s", "", text)
    if len(clean) < 8:
        return 0.0
    grams = [clean[index:index + 4] for index in range(len(clean) - 3)]
    counts = Counter(grams)
    repeated = sum(count for gram, count in counts.items() if count > 1)
    return round(repeated / len(grams), 2)


def filler_density(text: str) -> float:
    length = max(1, len(re.sub(r"\s", "", text)))
    hits = sum(count_fillers(text, FILLERS).values())
    return round(hits / length * 100, 2)


def number_consistency(answers: list[str], resume_text: str | None) -> float:
    """回答中的数字是否与简历中存在冲突（粗检）。无数字或无简历返回 0.5 中性。"""
    numbers = [match.group(0).strip() for match in NUMBERS.finditer(" ".join(answers))]
    numbers = [item for item in numbers if len(item) >= 2]
    if not numbers:
        return 0.5
    if not resume_text:
        return 0.5
    resume_numbers = {match.group(0).strip() for match in NUMBERS.finditer(resume_text)}
    if not resume_numbers:
        return 0.5
    conflicts = [item for item in set(numbers) if item not in resume_numbers]
    return round(1 - min(1.0, len(conflicts) / len(set(numbers))), 2)


def evasive_ratio(answers: list[str]) -> float:
    hits = sum(affirmative_occurrences(answer, word) for answer in answers
               if not constructive_uncertainty(answer) for word in EVASIVE)
    return round(min(1.0, hits / max(1, len(answers))), 2)


def question_type(question: str) -> str:
    if re.search(r"(项目|经历|做过|实习|负责|举.*例|过去.*处理)", question):
        return "EXPERIENCE"
    if re.search(r"(设计|方案|取舍|优化|如何处理|怎么解决|故障|场景)", question):
        return "SOLUTION"
    if re.search(r"(原理|区别|是什么|解释|定义|索引|复杂度|协议|事务|算法)", question):
        return "KNOWLEDGE"
    return "MOTIVATION"


def completeness(answers: list[str], questions: list[str | None] | None = None) -> float:
    """按题型检查信息槽位，数字是可选证据，不作为所有问题的必选项。"""
    results = []
    for index, answer in enumerate(answers):
        question = (questions[index] or "") if questions and index < len(questions) else "项目经历"
        kind = question_type(question)
        patterns = {
            "EXPERIENCE": [r"项目|实习|当时|背景|负责|参与", r"我|本人|主导|负责", r"通过|实现|设计|方案|采用|做了", r"结果|提升|降低|完成|上线|达到|减少|增长|解决"],
            "KNOWLEDGE": [r"是|指|用于|表示|本质", r"因为|通过|原理|实现|机制", r"例如|比如|场景|当|在", r"但是|不同|区别|限制|代价|不适用|需要|避免"],
            "SOLUTION": [r"目标|约束|需求|首先|问题", r"方案|设计|采用|使用|通过", r"取舍|代价|但是|相比|风险|成本|缺点", r"验证|监控|测试|指标|回滚|效果|边界"],
            "MOTIVATION": [r"我|个人|希望|选择|看重", r"因为|原因|考虑|匹配|适合", r"经验|能力|经历|了解|优势|岗位", r"计划|未来|期望|目标|愿意|贡献"],
        }[kind]
        results.append(sum(bool(re.search(pattern, answer)) for pattern in patterns) / len(patterns))
    return round(sum(results) / len(results), 2) if results else 0.0


def compute(questions: list[str | None], answers: list[str], resume_text: str | None = None) -> dict:
    """返回四个维度的客观分（0–1）与原始指标。"""
    if not answers:
        return {}
    text = " ".join(answers)
    coverage = [answer_relevance(question, answer) for question, answer in zip(questions, answers)] or [0.5]
    content = round(0.45 * structure_ratio(text) + 0.35 * number_consistency(answers, resume_text) + 0.2 * (1 - evasive_ratio(answers)), 2)
    relevance = round(sum(coverage) / len(coverage), 2)
    clarity = round(max(0.0, 1 - redundancy_ratio(text) * 1.5 - filler_density(text) / 20), 2)
    complete = completeness(answers, questions)
    return {
        "content": content,
        "relevance": relevance,
        "clarity": clarity,
        "completeness": complete,
        "metrics": {
            "questionTypes": [question_type(question or "") for question in questions],
            "structure": structure_ratio(text),
            "redundancy": redundancy_ratio(text),
            "fillerDensity": filler_density(text),
            "keywordCoverage": relevance,
            "evasive": evasive_ratio(answers),
        },
    }

"""Shared evidence requirements for reports and formal growth comparisons."""
from sqlalchemy import LargeBinary, and_, case, cast, exists, func, select
from sqlalchemy.orm import aliased

from app.db.models import Evaluation, EvaluationEvidence, Message, TrainingSession
from app.features.training.answer_turns import answer_turns, question_offset
from app.features.training.message_order import first_message_in_round
from app.features.training.policy import MIN_GROWTH_ROUNDS

DIMENSIONS = ("logic", "relevance", "correctness", "concision")


def verified_rows(rows, messages, training):
    by_id = {message.id: message for message in messages}
    turns = {turn.round_no: turn for turn in answer_turns(messages, training.channel)}
    return [row for row in rows if (
        row.dimension in DIMENSIONS
        and (question := by_id.get(row.question_message_id)) is not None
        and (answer := by_id.get(row.answer_message_id)) is not None
        and question.speaker == "AI" and answer.speaker == "USER"
        and (turn := turns.get(row.round_no)) is not None
        and turn.question.id == question.id and turn.answer.id == answer.id
        and answer.round_no == row.round_no
        and row.quote and row.quote.strip() and row.quote in answer.content
        and row.reason.strip() and row.next_action.strip()
    )]


def quality(evaluation, training, evidence):
    missing = [key for key in DIMENSIONS if key not in {row.dimension for row in evidence}]
    if (training.delivery or {}).get("rescoreRequired"):
        status = "PENDING_RESCORE"
    elif evaluation.review_required:
        status = "REVIEW_REQUIRED"
    elif evaluation.degraded:
        status = "RULE_BASED"
    elif training.current_round < MIN_GROWTH_ROUNDS:
        status = "LIMITED_SAMPLE"
    elif missing:
        status = "INSUFFICIENT_EVIDENCE"
    else:
        status = "VERIFIED"
    eligible = status == "VERIFIED" and training.status == "FINISHED" and training.language == "zh" and (training.assessment_context or {}).get("purpose") != "TRANSFER"
    return {"quality_status": status, "missing_evidence_dimensions": missing, "eligible_for_growth": eligible, "answered_rounds": training.current_round}


def formal_filters():
    """SQL equivalent of quality(), including exact, case-sensitive quote matching."""
    filters = [Evaluation.degraded.is_(False), TrainingSession.status == "FINISHED",
               Evaluation.review_required.is_(False),
               func.coalesce(TrainingSession.assessment_context["purpose"].as_string(), "PRACTICE") != "TRANSFER",
               TrainingSession.current_round >= MIN_GROWTH_ROUNDS,
               TrainingSession.language == "zh",
               TrainingSession.delivery["rescoreRequired"].as_boolean().is_not(True)]
    for dimension in DIMENSIONS:
        question, answer = aliased(Message), aliased(Message)
        filters.append(exists(select(1).select_from(EvaluationEvidence)
            .join(question, question.id == EvaluationEvidence.question_message_id)
            .join(answer, answer.id == EvaluationEvidence.answer_message_id)
            .where(
                EvaluationEvidence.evaluation_id == Evaluation.id,
                EvaluationEvidence.dimension == dimension,
                question.session_id == TrainingSession.id, answer.session_id == TrainingSession.id,
                question.speaker == "AI", answer.speaker == "USER",
                first_message_in_round(question), first_message_in_round(answer),
                answer.round_no == EvaluationEvidence.round_no,
                question.round_no == EvaluationEvidence.round_no - case((TrainingSession.channel == "TEXT", question_offset("TEXT")), else_=question_offset("VOICE")),
                func.length(func.trim(EvaluationEvidence.quote)) > 0,
                func.length(func.trim(EvaluationEvidence.reason)) > 0,
                func.length(func.trim(EvaluationEvidence.next_action)) > 0,
                func.instr(cast(answer.content, LargeBinary), cast(EvaluationEvidence.quote, LargeBinary)) > 0,
            ).correlate(Evaluation, TrainingSession)))
    return filters


def training_order():
    return (func.coalesce(TrainingSession.finished_at, TrainingSession.started_at).desc(),
            TrainingSession.started_at.desc(), TrainingSession.id.desc())


def earlier_training(training):
    # A stable lexicographic order independent of when a report was (re)graded.
    from sqlalchemy import or_
    ended = func.coalesce(TrainingSession.finished_at, TrainingSession.started_at)
    current_end = training.finished_at or training.started_at
    return or_(ended < current_end,
               and_(ended == current_end, TrainingSession.started_at < training.started_at),
               and_(ended == current_end, TrainingSession.started_at == training.started_at,
                    TrainingSession.id < training.id))

"""Research materials and strict two-rater calibration; never invent human scores."""
import csv
import hashlib
import json
import random
from pathlib import Path

from app.features.evaluations.agreement import summarize
from app.features.evaluations.standards import current_standard, DIMENSION_LABELS
from app.features.training.question_catalog import QUESTIONS, CATALOG_VERSION, transfer_specs

RATER_FIELDS = ["sample_id", "dimension", "conversation", "human_score", "note"]


def write_csv(path: Path, rows: list[dict], fields: list[str] | None = None):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('w', encoding='utf-8-sig', newline='') as handle:
        writer = csv.DictWriter(handle, fieldnames=fields or list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def read_csv(path: Path) -> list[dict]:
    with path.open(encoding='utf-8-sig', newline='') as handle:
        return list(csv.DictReader(handle))


def ordinal(value: str, location: str) -> int | None:
    if value is None or not str(value).strip():
        return None
    try:
        number = float(value)
    except (ValueError, TypeError):
        raise ValueError(f'{location}: 分数必须是 1–5 整数') from None
    if number not in {1, 2, 3, 4, 5}:
        raise ValueError(f'{location}: 分数必须是 1–5 整数')
    return int(number)


def indexed(rows: list[dict], name: str) -> dict[str, dict]:
    result = {}
    for row in rows:
        identity = row.get('sample_id', '').strip()
        if not identity or identity in result:
            raise ValueError(f'{name}: 缺少或重复 sample_id')
        result[identity] = row
    return result


def require_independent_raters(directory: Path):
    raters = json.loads((directory / 'raters.json').read_text(encoding='utf-8'))
    a, b = (str(raters.get(name, '')).strip() for name in ('raterA', 'raterB'))
    if not a or not b or a.casefold() == b.casefold():
        raise ValueError('raters.json 须记录两位不同评审的匿名编号，不能同一人填两份表')


def load_rater(path: Path, expected: dict[str, dict]) -> dict[str, int | None]:
    rows = indexed(read_csv(path), path.name)
    if set(rows) != set(expected):
        raise ValueError(f'{path.name}: 题目集合被改动，必须保留全部 sample_id')
    scores = {}
    for identity, row in rows.items():
        target = expected[identity]
        if row.get('dimension') != target['dimension']:
            raise ValueError(f'{identity}: 维度不匹配')
        if target.get('conversation') and row.get('conversation') != target['conversation']:
            raise ValueError(f'{identity}: 回答正文被改动，不能与原样本配对')
        scores[identity] = ordinal(row.get('human_score'), identity)
        if scores[identity] is not None and not row.get('conversation', '').strip():
            raise ValueError(f'{identity}: 没有真实回答正文，不能填分')
    return scores


def prepare_calibration(directory: Path) -> dict:
    directory.mkdir(parents=True, exist_ok=False)
    standard = current_standard()
    (directory / 'raters.json').write_text(json.dumps({'raterA': '', 'raterB': ''}, indent=2), encoding='utf-8')
    samples, labels, key = [], [], []
    for question in QUESTIONS:
        for case_type, answer in question['answers'].items():
            sample = {'id': question['id'] + '-' + case_type, 'familyId': question['id'],
                      'split': question['split'], 'competencyId': question['competencyId'],
                      'question': question['question'], 'answer': answer, 'caseType': case_type,
                      'source': 'AUTHORED_SYNTHETIC', 'standardHash': standard['hash']}
            samples.append(sample)
            group = hashlib.sha256(sample['id'].encode()).hexdigest()[:12]
            conversation = f"问：{sample['question']}\n答：{answer}"
            for dimension, label in DIMENSION_LABELS.items():
                identity = group + '-' + dimension
                labels.append({'sample_id': identity, 'dimension': label, 'conversation': conversation,
                               'human_score': '', 'note': ''})
                key.append({'sample_id': identity, 'group_id': group, 'case_id': sample['id'],
                            'family_id': question['id'], 'split': sample['split'], 'dimension': label,
                            'dimension_key': dimension, 'case_type': case_type, 'model_score': '',
                            'standard_hash': standard['hash'], 'source': sample['source']})
    for rater, seed in [('a', 20261125), ('b', 20261126)]:
        shuffled = list(labels)
        random.Random(seed).shuffle(shuffled)
        write_csv(directory / f'rater_{rater}.csv', shuffled)
    write_csv(directory / 'private/key.csv', key)
    private = directory / 'private'
    (private / 'samples.jsonl').write_text(''.join(json.dumps(item, ensure_ascii=False) + '\n' for item in samples), encoding='utf-8')
    (directory / 'standard.json').write_text(json.dumps(standard, ensure_ascii=False, indent=2), encoding='utf-8')
    (directory / 'standard.md').write_text('# 冻结评分标准\n\n版本：' + standard['id'] + '\n\n'
        + standard['systemPrompt'] + '\n\n人工校准状态：待采集。\n', encoding='utf-8')
    catalog = [{key: value for key, value in question.items() if key != 'answers'} for question in QUESTIONS]
    (directory / 'questions.json').write_text(json.dumps({'version': CATALOG_VERSION, 'reviewStatus': 'AUTHOR_DRAFT',
        'questions': catalog, 'transferQuestions': [item for domain in ('project','transaction','cache','diagnosis') for item in transfer_specs(domain)]}, ensure_ascii=False, indent=2), encoding='utf-8')
    manifest = {'schemaVersion': 1, 'standardId': standard['id'], 'standardHash': standard['hash'],
                'sampleCount': len(samples), 'questionFamilies': len(QUESTIONS),
                'developmentCases': sum(item['split'] == 'development' for item in samples),
                'holdoutCases': sum(item['split'] == 'holdout' for item in samples),
                'source': 'AUTHORED_SYNTHETIC', 'humanLabelsCollected': 0,
                'status': 'AWAITING_HUMAN_LABELS', 'reviewStatus': 'AUTHOR_DRAFT',
                'holdoutPolicy': '按题目整组划分；调参期间只使用 development。case_type 是编写意图，不是专家金标准。'}
    (directory / 'manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    (directory / 'README.md').write_text(
        '# 评分校准材料\n\n48 份人工编写的合成回答，不是真人数据。两位评审分别填写 rater_a.csv、rater_b.csv，只改 human_score 和 note。\n\n'
        '评分前阅读 standard.json 的四维行为锚点；每项填 1–5 整数。不得互看评分、模型分或 private 目录。\n\n'
        'private 目录由研究负责人保管。开发集与留出集按题目划分；留出集只在评分方案冻结后验收。\n\n'
        '所有人工分数留空。空白表只能得到“待采集”，不能生成一致率或训练有效性结论。题目难度与评分标准尚待真人审核。\n', encoding='utf-8')
    return manifest


def _expected_conversations(directory: Path, key: dict) -> dict:
    # Reconstruct immutable question text instead of trusting a modified rater A.
    samples = {row['id']: row for row in [json.loads(line) for line in (directory / 'private/samples.jsonl').read_text(encoding='utf-8').splitlines()]}
    expected = {}
    for identity, row in key.items():
        sample = samples[row['case_id']]
        expected[identity] = {'dimension': row['dimension'], 'conversation': f"问：{sample['question']}\n答：{sample['answer']}"}
    return expected


def _model_comparison(model_path: Path, selected: list, key: dict, a: dict, b: dict) -> dict | None:
    """模型分与两位评审的对照；模型结果不完整时返回 None。"""
    model = indexed(read_csv(model_path), 'model')
    if not set(selected) <= set(model):
        return None
    scores = {}
    for identity in selected:
        row = model[identity]
        if row.get('dimension') != key[identity]['dimension'] or row.get('standard_hash') != key[identity]['standard_hash']:
            raise ValueError(f'{identity}: 模型维度或评分标准版本不匹配')
        scores[identity] = ordinal(row.get('model_score'), identity)
    if any(value is None for value in scores.values()):
        return None
    return {dimension: {
        'vsRaterA': summarize([(scores[i], a[i]) for i in selected if key[i]['dimension'] == dimension]),
        'vsRaterB': summarize([(scores[i], b[i]) for i in selected if key[i]['dimension'] == dimension])}
        for dimension in DIMENSION_LABELS.values()}


def analyze_calibration(directory: Path, split: str = 'development', model_path: Path | None = None) -> dict:
    if split not in {'development', 'holdout'}:
        raise ValueError('只允许 development 或 holdout')
    key = indexed(read_csv(directory / 'private/key.csv'), 'key')
    expected = _expected_conversations(directory, key)
    a, b = load_rater(directory / 'rater_a.csv', expected), load_rater(directory / 'rater_b.csv', expected)
    selected = [identity for identity, row in key.items() if row['split'] == split]
    complete = all(a[identity] is not None and b[identity] is not None for identity in selected)
    output = {'status': 'HUMAN_LABELS_COMPLETE' if complete else 'AWAITING_HUMAN_LABELS', 'split': split,
              'answerCases': len({key[i]['group_id'] for i in selected}),
              'questionFamilies': len({key[i]['family_id'] for i in selected}),
              'expectedRatingsPerRater': len(selected),
              'raterACompleted': sum(a[i] is not None for i in selected),
              'raterBCompleted': sum(b[i] is not None for i in selected),
              'perDimension': {}, 'modelComparison': None,
              'note': '编写样本不等同真人样本；同题多种回答、同回答四维均不当作独立受试者。'}
    if not complete:
        return output
    require_independent_raters(directory)
    disagreements = []
    for dimension in DIMENSION_LABELS.values():
        ids = [i for i in selected if key[i]['dimension'] == dimension]
        output['perDimension'][dimension] = summarize([(a[i], b[i]) for i in ids])
        disagreements.extend(i for i in ids if a[i] != b[i])
    output['needsAdjudication'] = disagreements
    if model_path:
        comparison = _model_comparison(model_path, selected, key, a, b)
        if comparison is None:
            output['modelComparisonStatus'] = 'INCOMPLETE_MODEL_RESULTS'
        else:
            output['modelComparison'] = comparison
    return output

