@router.post("/preview")
async def preview_script(body: dict, user: CurrentUser) -> dict:
    """把一段改写读成语音，返回可播放地址。"""
    text = str(body.get("text") or "")
    if not text.strip():
        raise not_found("文本")
    try:
        url = await asyncio.wait_for(asyncio.to_thread(preview_speech, text), timeout=PREVIEW_TIMEOUT_SECONDS)
    except TimeoutError:
        raise AppError(504, "PREVIEW_TIMEOUT", "试听语音生成超时，请稍后重试。") from None
    except Exception as exc:
        logger.warning("scripts.preview_failed error_type=%s", type(exc).__name__)
        raise AppError(503, "PREVIEW_UNAVAILABLE", "试听语音暂不可用，请稍后重试。") from None
    return ok({"url": url})

"""Pair by answer round; the first message in dialogue_order wins duplicates."""
from dataclasses import dataclass
from app.db.models import Message
from app.features.training.language import is_repeat_request


@dataclass(frozen=True)
class AnswerTurn:
    round_no: int
    question: Message
    answer: Message


def question_round(answer_round: int, channel: str) -> int:
    return answer_round - question_offset(channel)


def question_offset(channel: str) -> int:
    return 1 if channel == "TEXT" else 0


def answer_turns(messages, channel: str) -> list[AnswerTurn]:
    questions = {}
    for message in messages:
        if message.speaker == "AI" and getattr(message, "kind", None) != "CONTROL" and not message.content.startswith("当然，我再说一遍："):
            questions.setdefault(message.round_no, message)
    turns = {}
    for answer in messages:
        if answer.speaker != "USER" or answer.round_no < 1 or getattr(answer, "kind", None) == "CONTROL" or is_repeat_request(answer.content):
            continue
        question = questions.get(question_round(answer.round_no, channel))
        if question is not None:
            # Non-counting "repeat the question" messages must not replace an answer.
            turns.setdefault(answer.round_no, AnswerTurn(answer.round_no, question, answer))
    return [turns[number] for number in sorted(turns)]

"""同题横向对比：同一道题在不同场次里的回答并排看。"""

from __future__ import annotations

from difflib import SequenceMatcher
import re

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from app.core.errors import not_found
from app.db.models import Evaluation, Message, TrainingSession
from app.features.training.answer_turns import answer_turns

SIMILARITY = 0.55
PUNCT = re.compile(r"[\s，。！？、；：""''（）()《》〈〉…—·.!?;:'\"()\[\]{}-]")


def _normalize(text: str) -> str:
    # 题目里可能带「（考察：信息完整）」这样的后缀，比对前去掉
    cleaned = re.sub(r"（考察：[^）]*）", "", text or "")
    return PUNCT.sub("", cleaned)


def _similar(left: str, right: str) -> float:
    a, b = _normalize(left), _normalize(right)
    if not a or not b:
        return 0.0
    return SequenceMatcher(None, a, b).ratio()


async def same_question_attempts(
    session: AsyncSession,
    user_id: str,
    session_id: str,
    round_no: int,
    limit: int = 5,
) -> list[dict]:
    current = await session.get(TrainingSession, session_id)
    if current is None or current.user_id != user_id:
        raise not_found("训练会话")
    if (current.assessment_context or {}).get("purpose") == "TRANSFER":
        return []

    current_messages = (
        await session.scalars(
            select(Message).where(Message.session_id == session_id).order_by(Message.round_no, Message.created_at)
        )
    ).all()
    current_turn = next((turn for turn in answer_turns(current_messages, current.channel) if turn.round_no == round_no), None)
    question = current_turn.question.content if current_turn else ""
    if not question:
        raise not_found("这一轮的题目")

    candidates = (
        await session.scalars(
            select(TrainingSession)
            .where(
                TrainingSession.user_id == user_id,
                TrainingSession.scene_id == current.scene_id,
                TrainingSession.status == "FINISHED",
            )
            .order_by(TrainingSession.started_at.desc())
            .limit(40)
        )
    ).all()

    attempts: list[dict] = []
    for item in candidates:
        if (item.assessment_context or {}).get("purpose") == "TRANSFER":
            continue
        if item.id == session_id:
            continue  # 当前这次不算「历史作答」
        messages = (
            await session.scalars(
                select(Message).where(Message.session_id == item.id).order_by(Message.round_no, Message.created_at)
            )
        ).all()
        for turn in answer_turns(messages, item.channel):
            if _similar(question, turn.question.content) < SIMILARITY:
                continue
            answer = turn.answer.content
            if not answer.strip():
                continue
            evaluation = await session.scalar(select(Evaluation).where(Evaluation.session_id == item.id))
            attempts.append(
                {
                    "sessionId": item.id,
                    "startedAt": item.started_at.isoformat(),
                    "isCurrent": item.id == session_id,
                    "question": turn.question.content,
                    "answer": answer,
                    "roundNo": turn.round_no,
                    "overallScore": evaluation.overall_score if evaluation else None,
                    "scores": {
                        "logic": evaluation.logic_score,
                        "relevance": evaluation.relevance_score,
                        "correctness": evaluation.correctness_score,
                        "concision": evaluation.concision_score,
                    }
                    if evaluation
                    else None,
                    "channel": item.channel,
                }
            )
            break
        if len(attempts) >= limit:
            break

    attempts.sort(key=lambda item: item["startedAt"], reverse=True)
    return attempts

"""One edit policy shared by the API and the interview settings UI."""
from app.core.errors import AppError
from app.db.models import TrainingPlan


async def conditions_locked_reason(session, training) -> str | None:
    if training.status != "ACTIVE":
        return "本场面试已结束，岗位和题目已固定；如需调整，请开始新的训练。"
    if (training.assessment_context or {}).get("purpose") == "TRANSFER":
        return "新题迁移需要独立完成本组题目，不能更换岗位和题目。"
    if training.plan_id and training.task_key:
        plan = await session.get(TrainingPlan, training.plan_id)
        task = next((item for item in (plan.tasks if plan else []) or [] if item.get("key") == training.task_key), None)
        if task and task.get("actionType") == "RETEST":
            return "同条件复测沿用原训练的岗位和题目，不能在本场更换。"
    if training.current_round > 0:
        return "已开始作答，岗位和题目已固定；如需调整，请开始新的训练。"
    return None


async def require_editable_conditions(session, training):
    reason = await conditions_locked_reason(session, training)
    if reason:
        raise AppError(409, "TRAINING_CONDITIONS_LOCKED", reason)

from typing_extensions import TypedDict

from langgraph.graph import END, START, StateGraph
from app.features.training.language import affirmative_occurrences


class ConversationState(TypedDict):
    round_no: int
    max_rounds: int
    user_text: str
    scene_title: str
    scene_id: str
    scene_category: str
    scene_difficulty: str
    role_name: str
    scene_background: str
    scene_goal: str
    core_idea: str
    resume_text: str
    stage: str
    flags: list[str]
    should_finish: bool
    finish_after_reply: bool
    mode: str
    depth: str
    language: str
    nervous: bool
    planned_question: str
    prompt: str


INAPPROPRIATE_PATTERNS = {
    "命令式表达": ["你必须", "少废话", "照我说的做"],
    "推卸责任": ["不关我的事", "都是他们的问题", "我没办法"],
    "绝对化表达": ["绝对不可能", "你总是", "你从来不"],
}

INTERVIEW_STAGE_GUIDANCE = {
    "HR 初面": "核验简历、基本情况、求职动机、薪资意向和到岗安排；不要把初面变成技术深挖。",
    "技术一面": "按应聘行业和岗位考察专业基础、常用方法、入门项目与本人职责；软件岗位可问编程和算法，其他岗位问对应专业基础。",
    "技术二面 / 复面": "按应聘行业和岗位深入原理、复杂方案、项目细节与取舍；软件岗位可问系统设计，其他岗位问对应高级方法。",
    "交叉面 / 总监面": "考察跨团队协作、综合判断、风险意识、成长潜力与团队匹配。",
    "HRBP/HR 终面": "核实薪酬条件、价值观、稳定性、工作安排和入职可行性；不转去技术考题。",
    "大老板 / 高管终面": "从业务价值、战略理解、责任担当和长期潜力做综合把关，避免细碎八股题。",
}


def safety_node(state: ConversationState) -> dict:
    flags = [
        label
        for label, patterns in INAPPROPRIATE_PATTERNS.items()
        if any(affirmative_occurrences(state["user_text"], pattern) for pattern in patterns)
    ]
    return {"flags": flags}


def stage_node(state: ConversationState) -> dict:
    next_round = state["round_no"] + 1
    if state.get("finish_after_reply") or next_round >= state["max_rounds"] - 1:
        stage = "CLOSING"
    elif next_round >= 8:
        stage = "CHALLENGE"
    elif next_round >= 3:
        stage = "DISCOVERY"
    else:
        stage = "OPENING"
    return {
        "round_no": next_round,
        "stage": stage,
        "should_finish": bool(state.get("finish_after_reply")) or next_round >= state["max_rounds"],
    }


def prompt_node(state: ConversationState) -> dict:
    is_foundation = state.get("scene_id", "").startswith("scene-foundation-") or state.get("scene_category") == "基础能力提升"
    stage_category = state.get("scene_category", "HR 初面")
    is_hr = stage_category in {"HR 初面", "HRBP/HR 终面"}
    stage_instruction = {
        "OPENING": "以真实面试官身份开始面试，围绕岗位提出一个聚焦问题，通常从自我介绍或求职动机开始。",
        "DISCOVERY": "针对回答中的经历追问细节，引导候选人补充背景、任务、行动、结果（STAR），每轮只追问一个点。",
        "CHALLENGE": "结合岗位提出进一步追问或反例，考察候选人的判断依据、复盘能力和临场应变。",
        "CLOSING": "进入面试收尾，提出最后一个聚焦问题；对方回答后才结束。",
    }[state["stage"]]
    if state["should_finish"]:
        stage_instruction = "候选人已经回答最后一个问题。只对刚才的回答作简短、自然的收尾，不要再提出任何问题、追问或让候选人补充。"
    elif is_foundation:
        stage_instruction = "保持场景角色，围绕训练目标和用户刚才的表达追问一个具体问题；不要切换成面试官或讲授课程。"
    elif is_hr:
